function score(book,p){const text=`${book.title||''} ${book.description||''} ${book.branch||''} ${(book.tags||book.categories||[]).join(' ')}`.toLowerCase(),jobHits=[...new Set((p.jobs||[]).flatMap(job=>(JOB_TERMS[job]||[job]).filter(term=>text.includes(term.toLowerCase()))))].length,purposeHits=(p.purposes||[]).flatMap(v=>v.split(/[·\s]/)).filter(term=>term.length>1&&text.includes(term.toLowerCase())).length,foreignDomain=Object.entries(JOB_TERMS).some(([job,terms])=>!(p.jobs||[]).includes(job)&&terms.some(term=>text.includes(term.toLowerCase()))),year=Number(book.year||String(book.publishedDate||'').slice(0,4));let value=25+Math.min(48,jobHits*12)+Math.min(18,purposeHits*6);if(!jobHits)value=foreignDomain?Math.min(value,35):Math.min(value,39);if(year>=new Date().getFullYear()-3)value+=4;return Math.max(10,Math.min(98,value));}
const FRESHNESS_YEARS={'최근 3년':3,'최근 5년':5,'최근 10년':10};
