function freshnessCutoff(value){const years=FRESHNESS_YEARS[value];return years?new Date().getFullYear()-years:0;}
function freshnessLabel(value){const cutoff=freshnessCutoff(value);return cutoff?`${value} (${cutoff}년 이후)`:value||'';}
