function kyoboUrl(book){const isbn=String(book.isbn||'').replace(/[^0-9X]/gi,''),query=isbn||book.title||'';return `https://search.kyobobook.co.kr/search?keyword=${encodeURIComponent(query)}`;}
function yes24Url(book){const sourceId=String(book.id||'').match(/^y:(\d+)$/)?.[1],storedId=String(book.storeLinks?.yes24||'').match(/yes24\.com\/product\/goods\/(\d+)/i)?.[1],itemId=sourceId||storedId;if(itemId)return `https://www.yes24.com/product/goods/${itemId}`;const params=new URLSearchParams({isbn:String(book.isbn||'').replace(/[^0-9X]/gi,''),title:book.title||''});return `/go/yes24?${params}`;}
function paperSiteUrl(site,title){const query=encodeURIComponent(title||'');if(site==='kiss')return `https://kiss.kstudy.com/Search/Result?query=${query}`;if(site==='riss')return `https://www.riss.kr/search/Search.do?colName=re_a_kor&isDetailSearch=Y&searchGubun=true&queryText=${encodeURIComponent(`znTitle,${title||''}`)}`;return `https://www.dbpia.co.kr/search/topSearch?searchOption=all&query=${query}`;}
function paperDirectUrl(paper){const doi=String(paper.doi||'').trim();if(/^https:\/\/doi\.org\/10\./i.test(doi))return doi;if(/^10\.\d{4,9}\//i.test(doi))return `https://doi.org/${doi}`;const landing=String(paper.landingUrl||'').trim();if(/^https:\/\//i.test(landing))return landing;return `https://search.crossref.org/?q=${encodeURIComponent(paper.title||'')}`;}
function cover(book){const isbn=String(book.isbn||'').replace(/[^0-9X]/gi,''),params=new URLSearchParams({isbn,title:book.title||'',author:(book.authors||[])[0]||'',publisher:book.publisher||''});if(book.thumbnail)params.set('source',book.thumbnail);const proxySrc=(isbn||book.title)?`/api/cover?${params}`:'',kyoboSrc=isbn?`https://contents.kyobobook.co.kr/sih/fit-in/400x0/pdt/${isbn}.jpg`:'',googleSrc=isbn?`https://books.google.com/books/content?vid=ISBN${isbn}&printsec=frontcover&img=1&zoom=2&source=gbs_api`:'',openLibrarySrc=isbn?`https://covers.openlibrary.org/b/isbn/${isbn}-L.jpg?default=false`:'',sources=[proxySrc,book.thumbnail,kyoboSrc,googleSrc,openLibrarySrc].filter((src,index,list)=>src&&list.indexOf(src)===index),src=sources.shift()||'';return src?`<div class="cover-wrap"><img class="real-cover" src="${escapeHtml(src)}" data-cover-sources="${escapeHtml(sources.join('|'))}" alt="${escapeHtml(book.title)} 표지" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="coverFallback(this)"><div class="cover blue" hidden><b>${escapeHtml(book.title)}</b></div></div>`:`<div class="cover blue"><b>${escapeHtml(book.title)}</b></div>`;}
