function localPaperTitleMeaning(title){const lower=title.toLowerCase(),terms=[];for(const [english,korean] of PAPER_TITLE_TERMS)if(lower.includes(english)&&!terms.includes(korean))terms.push(korean);return terms.length?`${terms.slice(0,5).join('·')}의 관계와 효과에 관한 연구`:'영문 제목의 연구 주제와 주요 효과를 분석한 논문';}
async function browserPaperTitleTranslation(title){if(/[가-힣]/.test(title)||!/[A-Za-z]{3}/.test(title))return '';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);try{const url=new URL('https://api.mymemory.translated.net/get');url.searchParams.set('q',title.slice(0,500));url.searchParams.set('langpair','en|ko');const response=await fetch(url,{signal:controller.signal}),data=await response.json(),translated=String(data.responseData?.translatedText||'').replace(/<[^>]*>/g,'').replace(/&quot;/g,'"').replace(/&amp;/g,'&').trim();return /[가-힣]/.test(translated)?translated:localPaperTitleMeaning(title);}catch{return localPaperTitleMeaning(title);}finally{clearTimeout(timer);}}
function paperCard(raw){const p=normalize(raw),fav=isFavorite(p),scoreValue=Math.max(0,Math.min(100,Number(p.match)||0)),doi=p.doi?` · DOI ${p.doi.replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'')}`:'',directUrl=paperDirectUrl(p),matchBadge=scoreValue?`<span class="match match-${matchGrade(scoreValue)}">적합도 ${scoreValue}% · ${matchGrade(scoreValue)}</span>`:'';return `<article class="book-card paper-card" data-paper-title="${escapeHtml(p.title)}"><div class="card-status">${matchBadge}<button class="favorite-button ${fav?'saved':''}" data-favorite="${escapeHtml(p.title)}" aria-label="논문 즐겨찾기" title="${fav?'나의 서재에서 제거':'나의 서재에 추가'}"><span>${fav?'♥':'♡'}</span></button></div><div class="card-main-link"><div class="cover-wrap paper-cover"><img class="real-cover" src="/paper-cover.png" alt="논문 표지" loading="lazy" decoding="async"><span>RESEARCH<br>PAPER</span></div><div class="book-info"><span class="paper-kind">추천 논문</span><h3 title="${escapeHtml(p.title)}">${escapeHtml(p.title)}</h3><p class="paper-meaning" hidden></p><p class="bibliography"><b>${escapeHtml(p.authors.join(', ')||'저자 미상')}</b><span>${escapeHtml(p.year||'연도 미상')} · ${escapeHtml(p.publisher||'학술지 미상')}${escapeHtml(doi)}</span></p></div></div><div class="card-actions paper-links" aria-label="${escapeHtml(p.title)} 논문 검색">${['kiss','riss','dbpia'].map(site=>`<a class="store-link ${site} checking" data-paper-site="${site}" target="_blank" rel="noopener" aria-disabled="true" tabindex="-1" title="자료 보유 여부 확인 중">${site==='dbpia'?'DBpia':site.toUpperCase()}</a>`).join('')}<a class="paper-direct-link" href="${escapeHtml(directUrl)}" target="_blank" rel="noopener">DOI·원문 상세 보기 <span>↗</span></a></div></article>`;}
async function hydratePaperAvailability(){const cards=$$('.paper-card[data-paper-title]');await Promise.all(cards.map(async card=>{const title=card.dataset.paperTitle,links=[...card.querySelectorAll('[data-paper-site]')],meaning=card.querySelector('.paper-meaning');try{const response=await fetch(`/api/paper-availability?v=2&title=${encodeURIComponent(title)}`),data=await response.json();if(!response.ok)throw new Error(data.error||'확인 실패');for(const link of links){const result=data.sites?.[link.dataset.paperSite];link.classList.remove('checking');if(result?.available){link.href=result.url||paperSiteUrl(link.dataset.paperSite,title);link.classList.remove('unavailable');link.setAttribute('aria-disabled','false');link.tabIndex=0;link.title=`${link.textContent}에서 논문 검색 결과 열기`;}else{link.removeAttribute('href');link.classList.add('unavailable');link.setAttribute('aria-disabled','true');link.tabIndex=-1;link.title=`${link.textContent}에서 확인되지 않은 논문입니다`;}}const translatedTitle=data.translatedTitle||await browserPaperTitleTranslation(title);if(translatedTitle&&meaning){meaning.textContent=`(${translatedTitle})`;meaning.hidden=false;}}catch{for(const link of links){link.classList.remove('checking');link.classList.add('unavailable');link.removeAttribute('href');link.title='자료 보유 여부를 확인하지 못해 비활성화되었습니다';}const translatedTitle=await browserPaperTitleTranslation(title);if(translatedTitle&&meaning){meaning.textContent=`(${translatedTitle})`;meaning.hidden=false;}}}));}
function renderBooks(){const p=profile(),paperMode=p.level===PAPER_LEVEL,stored=state.books.filter(book=>paperMode?book.type==='paper':book.type!=='paper'),books=stored.length?stored:(paperMode?[]:localRecommendations(p)),start=books.length?state.offset%books.length:0,visible=books.slice(start,start+6),end=start+visible.length;$('#bookGrid').innerHTML=visible.map(paperMode?paperCard:bookCard).join('');if(paperMode&&visible.length)hydratePaperAvailability();const summary=$('#resultSummary'),range=freshnessLabel(p.freshness);if(summary)summary.textContent=books.length?(paperMode?`${range} 조건과 선택 분야·목적을 모두 대조한 후보 ${books.length}편 중 ${start+1}~${end}편입니다. 적합도가 낮은 경우도 그대로 표시합니다.`:`${range} 조건을 적용해 후보 ${books.length}권 중 ${start+1}~${end}권을 보여드리고 있습니다.`):(paperMode?`${range} 범위에서 선택 분야와 목적을 함께 확인할 수 있는 논문을 찾지 못했습니다. 조건을 넓혀 다시 시도해 주세요.`:`${range} 조건을 충족하며 발행연도가 확인된 도서를 찾지 못했습니다.`);bindFavorites();}
function findBook(key){return [...state.books,...state.newBooks,...state.rankings,...catalog,...VERIFIED_NEW_BOOKS,...getShelf()].map(normalize).find(b=>b.isbn===key||b.title===key);}
async function syncFavorite(book,saved){try{await fetch('/api/favorite',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:rankingUserId(),saved,book})});if(state.view==='rankings')await loadRankings();}catch{}}
async function restoreShelf(){try{const res=await fetch(`/api/shelf?userId=${encodeURIComponent(rankingUserId())}`);if(!res.ok)return;const data=await res.json(),local=getShelf(),seen=new Set(local.map(book=>book.isbn||book.title)),merged=[...local,...(data.books||[]).filter(book=>!seen.has(book.isbn||book.title))];if(merged.length!==local.length){saveShelf(merged);renderLibrary();renderBooks();}merged.forEach(book=>syncFavorite(book,true));}catch{}}
async function migrateLegacyAccounts(){try{const legacy=JSON.parse(localStorage.getItem('gmuc-accounts')||'{}'),accounts=Object.entries(legacy).slice(0,200).map(([userId,legacyHash])=>({userId,legacyHash}));if(!accounts.length)return;await fetch('/api/account/migrate-legacy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accounts})});}catch{}}
function openAccountDialog(favoriteKey=''){pendingFavoriteKey=favoriteKey;passwordResetPending=false;$('#accountError').textContent='';$('#accountResetFields').hidden=true;$('#accountNewPassword').value='';$('#accountNewPasswordConfirm').value='';const dialog=$('#accountDialog');if(!dialog.open)dialog.showModal();setTimeout(()=>$('#accountId').focus(),0);}
function toggleFavorite(key){if(state.user==='guest'){openAccountDialog(key);toast('즐겨찾기는 방문자 ID 로그인 후 이용할 수 있습니다.');return;}const book=findBook(key);if(!book)return;let shelf=getShelf();const index=shelf.findIndex(b=>(book.isbn&&b.isbn===book.isbn)||b.title===book.title),saved=index<0;if(saved){shelf.unshift(book);toast('나의 서재에 영구 보관했습니다.');}else{shelf.splice(index,1);toast('나의 서재에서 삭제했습니다.');}saveShelf(shelf);renderCurrentCards();syncFavorite(book,saved);}
function bindFavorites(){$$('[data-favorite]').forEach(btn=>btn.onclick=()=>toggleFavorite(btn.dataset.favorite));}
function renderLibrary(){const shelf=getShelf(),hasPapers=shelf.some(book=>book.type==='paper');$('#libraryGrid').innerHTML=shelf.map(book=>book.type==='paper'?paperCard(book):bookCard(book)).join('');$('#libraryGrid').hidden=!shelf.length;$('#emptyLibrary').hidden=Boolean(shelf.length);$('#libraryCount').textContent=shelf.length;bindFavorites();if(hasPapers)hydratePaperAvailability();}
async function loadRankings(){const grid=$('#rankingGrid'),empty=$('#emptyRankings');try{const res=await fetch('/api/rankings');if(!res.ok)throw new Error();const data=await res.json(),source=data.books||[],frequency=new Map();source.forEach(book=>frequency.set(Number(book.favoriteCount)||0,(frequency.get(Number(book.favoriteCount)||0)||0)+1));let previousCount=null,currentRank=0;state.rankings=source.map((book,index)=>{const favoriteCount=Number(book.favoriteCount)||0;if(favoriteCount!==previousCount){currentRank=index+1;previousCount=favoriteCount;}return normalize({...book,match:0,rankingRank:currentRank,rankingTied:frequency.get(favoriteCount)>1,reason:`${favoriteCount}명이 즐겨찾기에 보관한 추천도서입니다.`});});grid.innerHTML=state.rankings.map(book=>`<div class="ranking-item ${book.rankingRank<=3?'top-rank':''}"><span class="rank-number ${book.rankingTied?'is-tied':''}">${book.rankingTied?`공동 ${book.rankingRank}`:book.rankingRank}</span><span class="heart-count">♥ ${book.favoriteCount}</span>${book.type==='paper'?paperCard(book):bookCard(book)}</div>`).join('');grid.hidden=!state.rankings.length;empty.hidden=Boolean(state.rankings.length);bindFavorites();if(state.rankings.some(book=>book.type==='paper'))hydratePaperAvailability();}catch{grid.hidden=true;empty.hidden=false;empty.querySelector('p').textContent='랭킹 서버에 연결할 수 없습니다. 잠시 후 다시 시도해 주세요.';}}
function renderCurrentCards(){renderBooks();renderLibrary();if(state.view==='new-books')loadNewBooks(false);}
function updateUserUI(){const id=state.user==='guest'?'방문자':state.user;$('#profileName').textContent=id;$('#profileName').title=id;$('#profileInitial').textContent=id[0].toUpperCase();$('#profileHint').textContent=state.isAdmin?(state.adminVerified?'관리자 이메일 인증됨':'관리자 인증 필요'):state.user==='guest'?'ID를 만들어 서재를 구분하세요':'내 서재 사용 중';$('#userName').textContent=id;$('#libraryOwner').textContent=id;$('#favoriteCount').textContent=getShelf().length;$('#libraryCount').textContent=getShelf().length;$('#adminNav').hidden=!state.isAdmin;if($('#challengePostAuthor'))$('#challengePostAuthor').value=state.user==='guest'?'':state.user;}
async function hash(value){const data=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return [...new Uint8Array(data)].map(v=>v.toString(16).padStart(2,'0')).join('');}
async function adminFetch(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'관리자 요청을 처리하지 못했습니다.');return data;}
function applyAdminState(data){state.isAdmin=true;state.adminVerified=Boolean(data.emailVerified);$('#adminNav').hidden=false;$('#adminAccountId').textContent=data.adminId||'admin';$('#adminEmail').textContent=data.maskedEmail||'설정되지 않음';const status=$('#adminEmailStatus'),verified=$('#adminVerifiedPanel'),verification=$('#adminVerificationPanel'),sendButton=$('#adminSendCode'),changePanel=$('#adminEmailChangePanel');status.textContent=state.adminVerified?'이메일 인증 완료':'이메일 인증 필요';status.classList.toggle('verified',state.adminVerified);status.classList.toggle('pending',!state.adminVerified);$('#adminVerificationText').textContent=state.adminVerified?'인증된 관리자 이메일입니다.':'실제 관리자 이메일로 최초 인증이 필요합니다.';verification.hidden=state.adminVerified;verified.hidden=!state.adminVerified;changePanel.hidden=!state.adminVerified;sendButton.disabled=false;sendButton.dataset.accessConfigured=String(Boolean(data.accessConfigured));updateUserUI();if(state.view==='admin')showAdminTab(state.adminVerified?challengeState.adminTab:'info');}
function sendAdminVerification(){const button=$('#adminSendCode'),error=$('#adminError'),success=$('#adminSuccess');error.textContent='';success.textContent='';if(button.dataset.accessConfigured!=='true'){error.textContent='Cloudflare 이메일 인증 연결을 확인하고 있습니다. 잠시 후 다시 시도해 주세요.';return;}const popup=window.open('/api/admin/email/access-verify','gmuc-admin-email-verification','popup,width=520,height=720');if(!popup)error.textContent='팝업이 차단되었습니다. 이 사이트의 팝업을 허용한 뒤 다시 눌러 주세요.';else success.textContent='열린 창에서 이메일 인증을 완료해 주세요.';}
