function resetHomeView(){state.view='curation';state.books=[];state.offset=0;hasRecommended=false;$('#results').hidden=true;$$('.chip.selected').forEach(button=>button.classList.remove('selected'));$$('[data-field]').forEach(field=>{field.selectedIndex=0;});syncPaperPreference();updateSelection();$$('.view').forEach(view=>view.classList.toggle('active',view.id==='curation'));$$('.nav [data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view==='curation'));scrollTo({top:0,behavior:'smooth'});}
