function openProfileDialog(){if(state.user==='guest'&&!state.isAdmin){openAccountDialog();return;}const title=$('#profileDialogTitle'),body=$('#profileDialogBody');title.textContent=state.isAdmin?'관리자 정보':'내 계정 정보';body.innerHTML=state.isAdmin?`<dl><div><dt>관리자 ID</dt><dd>admin</dd></div><div><dt>이메일</dt><dd>${escapeHtml($('#adminEmail').textContent||'설정되지 않음')}</dd></div><div><dt>인증 상태</dt><dd>${state.adminVerified?'인증 완료':'인증 필요'}</dd></div></dl>`:`<dl><div><dt>사용자ID</dt><dd>${escapeHtml(state.user)}</dd></div><div><dt>서재</dt><dd>${getShelf().length}권</dd></div></dl>`;$('#profileDelete').hidden=state.isAdmin;const dialog=$('#profileDialog');if(!dialog.open)dialog.showModal();}
