async function deleteCurrentAccount(password){const deletedUser=state.user,response=await fetch('/api/account/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'회원탈퇴를 처리하지 못했습니다.');localStorage.removeItem(`gmuc-shelf:${deletedUser}`);try{const legacy=JSON.parse(localStorage.getItem('gmuc-accounts')||'{}');if(legacy[deletedUser]){delete legacy[deletedUser];localStorage.setItem('gmuc-accounts',JSON.stringify(legacy));}}catch{localStorage.removeItem('gmuc-accounts');}state.user='guest';state.isAdmin=false;state.adminVerified=false;localStorage.setItem('gmuc-current-user','guest');$('#accountDeleteDialog').close();resetHomeView();updateUserUI();renderLibrary();renderBooks();toast('회원탈퇴가 완료되어 계정과 저장 데이터가 삭제됐습니다.');}
async function login(id,password,newPassword=''){if(id==='admin'){const data=await adminFetch('/api/admin/login',{method:'POST',body:JSON.stringify({id,password})});state.user='admin';localStorage.setItem('gmuc-current-user','guest');applyAdminState(data);renderLibrary();renderBooks();return {admin:true};}if(state.isAdmin)await fetch('/api/admin/logout',{method:'POST'}).catch(()=>{});state.isAdmin=false;state.adminVerified=false;const accounts=JSON.parse(localStorage.getItem('gmuc-accounts')||'{}'),response=await fetch('/api/account/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,password,newPassword,legacyPasswordHash:accounts[id]||''})}),data=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data.error||'로그인 요청을 처리하지 못했습니다.');error.code=data.code;throw error;}if(accounts[id]){delete accounts[id];localStorage.setItem('gmuc-accounts',JSON.stringify(accounts));}state.user=id;state.view='curation';localStorage.setItem('gmuc-current-user',id);updateUserUI();renderLibrary();renderBooks();showView('curation');return {admin:false,created:Boolean(data.created),passwordChanged:Boolean(data.passwordChanged)};}

function adminDate(value){return value?new Date(value*1000).toLocaleString('ko-KR',{year:'2-digit',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'기록 없음';}
async function loadAdminUsers(){if(!state.adminVerified)return;const query=$('#adminUserSearch').value.trim(),data=await adminFetch(`/api/admin/users?query=${encodeURIComponent(query)}`);$('#adminUserCount').textContent=data.summary?.userCount||0;$('#adminBookCount').textContent=(data.summary?.bookCount||0).toLocaleString();$('#adminBookTypeCount').textContent=(data.summary?.bookTypeCount||0).toLocaleString();const rows=$('#adminUserRows'),users=data.users||[];rows.innerHTML=users.map(user=>`<tr class="${user.isAdmin?'admin-system-row':''}"><td><b class="admin-user-id ${user.isAdmin?'is-admin':''}">${escapeHtml(user.isAdmin?'admin(관리자)':user.userId)}</b></td><td>${escapeHtml(adminDate(user.lastLoginAt))}<span class="admin-user-meta">생성 ${escapeHtml(adminDate(user.createdAt))}</span></td><td><span class="admin-usage">${Number(user.recommendedBookCount||0).toLocaleString()}권</span></td><td><div class="admin-row-actions"><button data-admin-action="recommendations" data-user-id="${escapeHtml(user.userId)}" type="button">추천도서 초기화</button>${user.isAdmin?'':`<button class="danger" data-admin-action="password" data-user-id="${escapeHtml(user.userId)}" type="button">비밀번호 초기화</button>`}</div></td></tr>`).join('');$('#adminUsersEmpty').hidden=Boolean(users.length);}
