async function showView(id){if(id==='admin'&&!state.isAdmin){openAccountDialog();return;}if(id==='library'&&state.user==='guest'&&!state.isAdmin){pendingLibraryView=true;openAccountDialog();toast('나의 서재는 로그인 후 이용할 수 있습니다.');return;}state.view=id;$$('.view').forEach(v=>v.classList.toggle('active',v.id===id));$$('.nav [data-view],.header-library[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===id));scrollTo({top:0,behavior:'smooth'});if(id==='library')renderLibrary();if(id==='new-books')loadNewBooks();if(id==='rankings')loadRankings();if(id==='challenges')await loadChallenges(!challengeState.boards.length);if(id==='admin')loadAdminStatus(false).catch(err=>toast(err.message));}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2300);}
function normalizeGoogleClient(item,branch){const v=item.volumeInfo||{},isbn=(v.industryIdentifiers||[]).find(id=>id.type==='ISBN_13')?.identifier||(v.industryIdentifiers||[])[0]?.identifier||'';return normalize({title:v.title||'',authors:v.authors||[],publisher:v.publisher||'',publishedDate:v.publishedDate||'',pageCount:v.pageCount||0,description:v.description||'',categories:v.categories||[],isbn,thumbnail:(v.imageLinks?.thumbnail||'').replace(/^http:/,'https:'),source:'Google Books',branch,reason:`${branch} 검색 가지에서 찾은 도서입니다.`});}
async function browserSearch(p){const jobQueries=p.jobs.flatMap(job=>CLIENT_SEARCH_TREE[job]||[job]),purposeQueries=(p.purposes||[]).flatMap(purpose=>(CLIENT_PURPOSE_TREE[purpose]||[]).map(term=>`${p.jobs[0]||'공공기관'} ${term}`)),all=[...new Set([...purposeQueries,...jobQueries])],start=Math.floor(Date.now()/60000)%Math.max(1,all.length),queries=[...all.slice(start),...all.slice(0,start)].slice(0,12),groups=[],wantsCertificate=p.purposes.includes('자격증·시험'),requests=queries.flatMap(query=>[0,40].map(startIndex=>(async()=>{try{const url=new URL('https://www.googleapis.com/books/v1/volumes');url.searchParams.set('q',query);url.searchParams.set('printType','books');url.searchParams.set('langRestrict','ko');url.searchParams.set('maxResults','40');url.searchParams.set('startIndex',String(startIndex));const res=await fetch(url);if(!res.ok)return [];const data=await res.json();return (data.items||[]).map(item=>normalizeGoogleClient(item,query)).filter(book=>book.title&&book.isbn&&matchesHardFilters(book,p)&&score(book,p)>=40&&(wantsCertificate||!EXAM_TITLE.test(book.title)));}catch{return [];}})()));for(const result of await Promise.all(requests))if(result.length)groups.push(result);const seen=new Set(),books=[];while(books.length<300&&groups.some(group=>group.length)){for(const group of groups){const book=group.shift();if(!book||seen.has(book.isbn))continue;seen.add(book.isbn);books.push({...book,match:score(book,p)});}}return books;}
async function recommend(){const p=profile(),paperMode=p.level===PAPER_LEVEL;if(!p.jobs.length)return toast('1번 직렬 및 업무 분야를 선택해 주세요.');if(!p.purposes.length)return toast('2번 독서 목적을 선택해 주세요.');if(!p.level||!p.freshness||!p.practical)return toast('3번 세부 독서 취향을 모두 선택해 주세요.');const button=$('#recommendButton');button.disabled=true;button.classList.remove('renewal');button.querySelector('span').textContent=paperMode?'선택 조건과 학술논문 대조 중…':'다양한 검색 가지 분석 중…';button.querySelector('i').textContent='…';try{let live=[];const res=await fetch('/api/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}),data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'추천 결과를 불러오지 못했습니다.');if(paperMode){live=(data.books||[]).filter(item=>item.type==='paper'&&item.title).map(normalize);state.books=live;}else{live=(data.books||[]).filter(item=>item.type!=='paper'&&item.isbn&&item.title).map(normalize);if(live.length<12)live=[...live,...await browserSearch(p)];const seen=new Set();live=live.filter(b=>matchesHardFilters(b,p)&&!seen.has(b.isbn)&&(seen.add(b.isbn),true));state.books=live.length?live:localRecommendations(p);}}catch(error){if(paperMode){state.books=[];toast(error.message||'논문 검색 서비스에 연결하지 못했습니다.');}else{const seen=new Set(),live=(await browserSearch(p)).filter(b=>matchesHardFilters(b,p)&&!seen.has(b.isbn)&&(seen.add(b.isbn),true));state.books=live.length?live:localRecommendations(p);}}finally{hasRecommended=true;state.offset=0;if(state.user!=='guest')fetch('/api/account/recommendations/log',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bookCount:state.books.length,profile:p})}).catch(()=>{});$('#results').hidden=false;renderBooks();button.disabled=false;button.querySelector('span').textContent='AI 추천 시작하기';button.querySelector('i').textContent='→';$('#results').scrollIntoView({behavior:'smooth'});}}
function miniCard(raw){const b=normalize(raw),fav=isFavorite(b);return `<article class="mini-book"><a class="mini-main-link" href="${kyoboUrl(b)}" target="_blank" rel="noopener" aria-label="${escapeHtml(b.title)} 교보문고에서 보기">${cover(b)}<div><span class="mini-source">NEW BOOK</span><h3>${escapeHtml(b.title)}</h3><p>${escapeHtml(b.authors.join(', ')||'저자 미상')}</p><small>${escapeHtml(b.year||'연도 미상')} · ${escapeHtml(b.publisher||'출판사 미상')}</small></div></a><button class="favorite-button ${fav?'saved':''}" data-favorite="${escapeHtml(b.isbn||b.title)}" aria-label="즐겨찾기"><span>${fav?'♥':'♡'}</span></button></article>`;}
async function loadNewBooks(fetchLive=true){let live=[];if(fetchLive){try{const res=await fetch('/api/new-books');if(res.ok){const data=await res.json();live=(data.books||[]).filter(b=>b.title&&b.isbn&&b.authors?.length&&b.publisher);}}catch{}}const seen=new Set(),books=[...live,...VERIFIED_NEW_BOOKS].map(normalize).filter(b=>{if(!b.title||!b.isbn||!b.authors.length||!b.publisher)return false;const key=b.isbn;if(seen.has(key))return false;seen.add(key);return true;}).slice(0,20);state.newBooks=books;const track=$('#newBooksTrack');if(!books.length){track.innerHTML='<div class="verified-empty">현재 서지정보가 확인된 신간 도서가 없습니다.</div>';track.dataset.itemCount='0';return;}track.innerHTML=[...books,...books].map(miniCard).join('');track.dataset.itemCount=String(books.length);bindFavorites();resetCarousels();}
function slideCarousel(){const track=$('#newBooksTrack'),viewport=$('#newBooksViewport'),card=track?.querySelector('.mini-book');if(!track||!viewport||!card)return;const step=card.getBoundingClientRect().width+12,count=Number(track.dataset.itemCount||0),cycleWidth=step*count,next=viewport.scrollLeft+step;viewport.scrollTo({left:next,behavior:'smooth'});if(next>=cycleWidth-2){clearTimeout(slideCarousel.resetTimer);slideCarousel.resetTimer=setTimeout(()=>{viewport.style.scrollBehavior='auto';viewport.scrollLeft=Math.max(0,viewport.scrollLeft-cycleWidth);requestAnimationFrame(()=>viewport.style.scrollBehavior='smooth');},520);}}
function resetCarousels(){clearInterval(resetCarousels.timer);const viewport=$('#newBooksViewport');if(viewport)viewport.scrollLeft=0;resetCarousels.timer=setInterval(()=>{if(state.view==='new-books')slideCarousel();},3200);}
